questionvariables.text:
/*Randomization of the coefficients of u and values of y's and xy's*/
xy_1: rand(5)+1; /*1 xy_1:rand(3)+1;*/ 
xy_2: 2+xy_1; /*3 xy_2:rand_with_prohib(1,4,[xy_1]);*/
y_1: rand(5)+2; /*2 y_1:rand(3)+2;*/
y_2: 4+y_1; /*6 y_2:rand_with_prohib(1,6,[y_1]);*/

xx:x=(v/(y_2*u));
yy:y=y_1*u;

/*Worked solution code block*/
uu:ev(yy,u,y=y_2); u_1:solve(uu)[1];
xxx:x=(v/(y_2*u))*(y_1*u); vv:ev(xxx,v,x=xy_2); v_1:solve(vv)[1]; 
uu_1:ev(yy,u,y=y_1); u_2:solve(uu_1)[1];
xxx_1:x=(v/(y_2*u))*(y_1*u); vv_2:ev(xxx_1,v,x=xy_1); v_2:solve(vv_2)[1]; 
diff_xu:diff(rhs(xx),u); diff_yu:diff(rhs(yy),u); 
diff_xv:diff(rhs(xx),v); diff_yv:diff(rhs(yy),v); 
transformation_J:diff_xu*diff_yv-diff_xv*diff_yu;
expr:(rhs(xx)*rhs(yy)^3*(-1*(transformation_J)));
int_xy_v:int(expr,v);
int_xy_v1:int(expr,v,rhs(u_1),rhs(v_1));
int_xy_u:int(int_xy_v1,u);
int_xy_u1:int(int_xy_v1,u,rhs(u_2),rhs(v_2));

/*Model answers*/
ta1: rhs(u_1);
ta2: rhs(v_1);
ta3: rhs(u_2);
ta4: rhs(v_2);


ax1:rand(7)-4;
ay1:rand(7)-4;
ax2:rand(7)-4;
ay2:rand(7)-4;
ax3:rand(7)-4;
ay3:rand(7)-4;
ax4:rand(7)-4;
ay4:rand(7)-4;

ta5:[ta3,ta2];
ta6:[ta1,ta2];
ta7:[ta3,ta4];
ta8:[ta1,ta4];

ta9:ta3<=u and u<=ta1;   /*transformed limits of u*/
ta10:ta4<=v and v<=ta2;    /*transformed limits of v*/
ta11:matrix([diff_xu,diff_xv],[diff_yu,diff_yv]);
ta12: transformation_J; /*the determinant*/
ta13: int_xy_u1;
